   projection=parser['parse'](work/'private-storage-agent-protocol.trace',v['first_response']['value']['function_ids'])
   p=work/'owned-acquire-responses.json';p.write_text(json.dumps(projection,indent=2)+'\n');p.chmod(0o600)
   v['native_projection']={'path':str(p.relative_to(root)),'sha256':sha(p.read_bytes()),'value':projection}
