worker=Path('.local/e2e')/name;pin=json.loads((worker/'host-process-namespace.json').read_bytes());s=os.stat('/proc/self/ns/pid');ns={'device':s.st_dev,'inode':s.st_ino};sha=lambda b:hashlib.sha256(b).hexdigest()
assert ns==pin['pid_namespace']and sha(Path('/proc/sys/kernel/random/boot_id').read_bytes())==pin['boot_id_sha256']
work=worker/('storage-response-observer-controller-'+uuid4().hex);work.mkdir(mode=0o700)
program=Path('.local/observe-storage-response-finalization.py');raw=program.read_bytes();(work/program.name).write_bytes(raw)
controller=Path(__file__);(work/controller.name).write_bytes(controller.read_bytes())
v={'finished':False,'joined':False,'groups_added':0,'worker':name,'started_at_ns':time.time_ns(),'pid_namespace':ns,'boot_id_sha256':pin['boot_id_sha256'],'observer_program':{'path':str(program),'sha256':sha(raw)},'controller_sha256':sha(controller.read_bytes()),'controller_identity':{'pid':os.getpid(),'birth':Path('/proc/self/stat').read_text().rsplit(')',1)[1].split()[19],'cgroup':Path('/proc/self/cgroup').read_text()}}
def save():
 p=work/'result.pending';p.write_text(json.dumps(v,indent=2)+'\n');p.chmod(0o600);p.replace(work/'result.json')
save();print(json.dumps({'controller_result':str(work/'result.json')}),flush=True)
child=None;primary=None;secondary=[];v['finalization_failures']=[]
try:
 with(work/'observer.stdout').open('xb')as stdout,(work/'observer.stderr').open('xb')as stderr:
  child=subprocess.Popen([sys.executable,'-B',str(program),name],stdin=subprocess.DEVNULL,stdout=stdout,stderr=stderr)
  v['observer_identity']={'pid':child.pid,'birth':Path('/proc',str(child.pid),'stat').read_text().rsplit(')',1)[1].split()[19],'cgroup':Path('/proc',str(child.pid),'cgroup').read_text()};save()
  try:code=child.wait(timeout=1200)
  except subprocess.TimeoutExpired:
   v['deadline_expired']=True
   raise
  v.update(finished=True,joined=True,returncode=code,finished_at_ns=time.time_ns())
except BaseException as error:
 primary=error;v['failure']={'type':type(error).__name__,'errno':getattr(error,'errno',None),'message_sha256':sha(str(error).encode())}
finally:
 def retain_secondary(step,error):
  secondary.append(error);v['finalization_failures'].append({'step':step,'type':type(error).__name__,'errno':getattr(error,'errno',None),'message_sha256':sha(str(error).encode())})
 if child is not None and child.returncode is None:
  try:child.terminate()
  except BaseException as error:retain_secondary('terminate',error)
  try:child.wait(timeout=110)
  except subprocess.TimeoutExpired:
   try:child.kill()
   except BaseException as error:retain_secondary('kill',error)
   try:child.wait(timeout=10)
   except BaseException as error:retain_secondary('wait_after_kill',error)
  except BaseException as error:retain_secondary('wait',error)
 if child is not None:
  try:
   code=child.poll();v.update(joined=code is not None,returncode=code,finished_at_ns=time.time_ns())
  except BaseException as error:retain_secondary('poll',error)
 for key in('stdout','stderr'):
  try:
   p=work/('observer.'+key);raw=p.read_bytes();v[key]={'path':str(p),'sha256':sha(raw),'bytes':len(raw)}
  except BaseException as error:retain_secondary('retain_'+key,error)
 try:save()
 except BaseException as error:retain_secondary('save',error)
 try:print(json.dumps({'controller_result':str(work/'result.json'),'returncode':v.get('returncode'),'joined':v['joined'],'groups_added':0,'failure':v.get('failure'),'finalization_failures':v['finalization_failures']}),flush=True)
 except BaseException as error:retain_secondary('print',error)
 if secondary:
  try:print(json.dumps({'event':'controller-finalization-failed','primary':v.get('failure'),'secondary':v['finalization_failures'],'finished':v['finished'],'joined':v['joined'],'returncode':v.get('returncode')}),file=sys.stderr,flush=True)
  except BaseException as error:retain_secondary('diagnostic_print',error)
if primary is not None:raise primary
if secondary:raise secondary[0]
assert v['finished']and v['joined']and v['returncode']is not None
sys.exit(v['returncode'])

